def metric(data: pd.DataFrame) -> float:
    import numpy as np

    v = np.array([1.0, 0.9, 0.8, 0.7, 0.6, 0.5])

    tally_matches = 0
    disagreement_trials = 0

    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])

        a_wins = np.sum(a > b)
        b_wins = np.sum(b > a)

        wadd_a = np.dot(a, v)
        wadd_b = np.dot(b, v)

        tally_pref = None
        if a_wins > b_wins:
            tally_pref = 0
        elif b_wins > a_wins:
            tally_pref = 1

        wadd_pref = None
        if wadd_a > wadd_b:
            wadd_pref = 0
        elif wadd_b > wadd_a:
            wadd_pref = 1

        if tally_pref is not None and wadd_pref is not None and tally_pref != wadd_pref:
            disagreement_trials += 1
            if row['response'] == tally_pref:
                tally_matches += 1

    if disagreement_trials == 0:
        return 0.5

    return float(tally_matches / disagreement_trials)

